package com.umc.pediupatrao.service;

import com.umc.pediupatrao.audit.Auditoria;
import com.umc.pediupatrao.audit.AuditoriaService;
import com.umc.pediupatrao.entity.Pedido;
import com.umc.pediupatrao.repository.PedidoRepository;
import com.umc.pediupatrao.repository.ProdutoRepository;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;
import java.math.BigDecimal; import java.math.RoundingMode; import java.time.Instant; import java.util.*;

@Service public class PedidoService {
 private final PedidoRepository pedidos; private final ProdutoRepository produtos; private final AuditoriaService auditoria;
 public PedidoService(PedidoRepository p,ProdutoRepository prod,AuditoriaService a){pedidos=p;produtos=prod;auditoria=a;}
 public Pedido criarPedido(Pedido p){String user=usuario(); p.setId(null); p.setStatus("RECEBIDO");p.setDescontoPercentual(BigDecimal.ZERO);p.setValorDesconto(BigDecimal.ZERO);p.setResponsavelRegistro(user);p.setDataHoraEntrada(Instant.now());p.setResponsavelSaida(null);p.setDataHoraSaida(null);calcular(p);Pedido salvo=pedidos.save(p);auditoria.registrar("CRIACAO","Pedido",salvo.getId(),Map.of("status",new Auditoria.Alteracao(null,salvo.getStatus()),"valorTotal",new Auditoria.Alteracao(null,salvo.getValorTotal())),null);return salvo;}
 public List<Pedido> listarPedidos(){return pedidos.findAll();}
 public Pedido atualizarStatus(String id,String novo){Pedido p=obter(id);String atual=normalizar(p.getStatus());if(atual.equals("CANCELADO")||atual.equals("FINALIZADO"))throw new IllegalArgumentException("Pedido encerrado não pode ser alterado.");String destino=normalizar(novo);Map<String,String> prox=Map.of("RECEBIDO","EM PREPARAÇÃO","EM PREPARAÇÃO","PRONTO","PRONTO","SAIU PARA ENTREGA","SAIU PARA ENTREGA","FINALIZADO","RETIRADO","FINALIZADO");boolean valido=destino.equals(prox.get(atual))||(atual.equals("PRONTO")&&destino.equals("RETIRADO"));if(!valido)throw new IllegalArgumentException("Transição inválida: "+atual+" → "+destino);p.setStatus(destino);if(destino.equals("SAIU PARA ENTREGA")||destino.equals("RETIRADO")){p.setResponsavelSaida(usuario());p.setDataHoraSaida(Instant.now());}if(destino.equals("FINALIZADO")&&p.getDataHoraSaida()==null)throw new IllegalArgumentException("Só é possível finalizar após saída ou retirada.");Pedido salvo=pedidos.save(p);auditoria.registrar("MUDANCA_STATUS","Pedido",id,Map.of("status",new Auditoria.Alteracao(atual,destino)),null);return salvo;}
 public Pedido aplicarDesconto(String id,BigDecimal percentual){exigirGerente();Pedido p=obter(id);validarAberto(p);if(percentual==null||percentual.compareTo(BigDecimal.ZERO)<0||percentual.compareTo(new BigDecimal("20"))>0)throw new IllegalArgumentException("Desconto deve ser de 0% a 20%.");BigDecimal antigo=p.getValorTotal();BigDecimal descontoAnterior=p.getDescontoPercentual()==null?BigDecimal.ZERO:p.getDescontoPercentual();BigDecimal desc=p.getValorSubtotal().multiply(percentual).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP);p.setDescontoPercentual(percentual);p.setValorDesconto(desc);p.setValorTotal(p.getValorSubtotal().subtract(desc).max(BigDecimal.ZERO));Pedido salvo=pedidos.save(p);auditoria.registrar("DESCONTO","Pedido",id,Map.of("descontoPercentual",new Auditoria.Alteracao(descontoAnterior,percentual),"valorTotal",new Auditoria.Alteracao(antigo,salvo.getValorTotal())),"Aplicação de desconto");return salvo;}
 public Pedido cancelar(String id,String justificativa){exigirGerente();Pedido p=obter(id);validarAberto(p);if(justificativa==null||justificativa.isBlank())throw new IllegalArgumentException("Justificativa obrigatória para cancelamento.");String antigo=p.getStatus();p.setStatus("CANCELADO");p.setJustificativaCancelamento(justificativa.trim());Pedido salvo=pedidos.save(p);auditoria.registrar("CANCELAMENTO","Pedido",id,Map.of("status",new Auditoria.Alteracao(antigo,"CANCELADO"),"justificativa",new Auditoria.Alteracao(null,justificativa.trim())),justificativa.trim());return salvo;}
 private void calcular(Pedido p){BigDecimal subtotal=BigDecimal.ZERO;if(p.getItens()!=null&&!p.getItens().isEmpty()){for(Pedido.ItemPedido i:p.getItens()){if(i.getNome()==null||i.getQuantidade()<1)throw new IllegalArgumentException("Cada item precisa de nome e quantidade positiva.");var prod=produtos.findAll().stream().filter(x->x.getNome()!=null&&x.getNome().equalsIgnoreCase(i.getNome())&&!Boolean.FALSE.equals(x.getAtivo())).findFirst().orElseThrow(()->new IllegalArgumentException("Produto não encontrado/ativo: "+i.getNome()));BigDecimal preco=BigDecimal.valueOf(prod.getPreco()==null?0:prod.getPreco());i.setPrecoUnitario(preco);subtotal=subtotal.add(preco.multiply(BigDecimal.valueOf(i.getQuantidade())));}}else if(p.getQuantidade()>0){p.setItens(new ArrayList<>());Pedido.ItemPedido i=new Pedido.ItemPedido();i.setNome((p.getTipoPizza()==null?"Pedido":p.getTipoPizza())+(p.getSabor()==null?"":" - "+p.getSabor()));i.setQuantidade(p.getQuantidade());i.setPrecoUnitario(BigDecimal.ZERO);p.getItens().add(i);}p.setValorSubtotal(subtotal);p.setValorDesconto(BigDecimal.ZERO);p.setValorTotal(subtotal);}
 private Pedido obter(String id){return pedidos.findById(id).orElseThrow(()->new NoSuchElementException("Pedido não encontrado."));}
 private void validarAberto(Pedido p){if(Set.of("SAIU PARA ENTREGA","RETIRADO","FINALIZADO","CANCELADO").contains(normalizar(p.getStatus())))throw new IllegalArgumentException("Operação permitida somente antes da saída.");}
 private void exigirGerente(){Authentication a=SecurityContextHolder.getContext().getAuthentication();if(a==null||a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_GERENTE")))throw new AccessDeniedException("Somente GERENTE pode executar esta operação.");}
 private String usuario(){Authentication a=SecurityContextHolder.getContext().getAuthentication();return a==null?"sistema":a.getName();}
 private String normalizar(String s){if(s==null)return "RECEBIDO";String v=s.trim().toUpperCase(Locale.ROOT).replace('_',' ');return v.replace("EM PREPARACAO","EM PREPARAÇÃO").replace("SAIU PARA ENTREGA","SAIU PARA ENTREGA");}
}
